const s = wb.getWorksheet('Before');
const after = wb.getWorksheet('After');
for (let r = 2; r <= 9; r++) {
  const cell = s.getRange(`A${r}`);
  const t = String(cell.getValue());
  const i = t.search(/[A-Za-z]/);
  if (i < 0) continue;
  const left = t.slice(0, i).trimEnd();
  const right = t.slice(i);
  s.getRange(`A${r}`).setValue("'" + left);
  s.getRange(`B${r}`).setValue("'" + right);
}
const out = [];
for (let r = 1; r <= 12; r++) {
  const a = s.getRange(`A${r}`).getValue(), b = s.getRange(`B${r}`).getValue();
  const aa = after.getRange(`A${r+1}`).getValue(), ab = after.getRange(`B${r+1}`).getValue();
  out.push([r, typeof a, JSON.stringify(a), s.getRange(`A${r}`).getText?.(), JSON.stringify(b), 'matchAfter', a===aa, b===ab].join(' | '));
}
out.join('\n')

